<?php require_once __DIR__.'/../includes/functions.php';require_admin();$type=($_GET['type']??'subject')==='skill'?'skill':'subject';$table=$type==='skill'?'skills':'subjects';$label=ucfirst($type);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'';if($act==='save'){$name=trim($_POST['name']??'');$id=(int)($_POST['id']??0);if($name){if($id)db()->prepare("UPDATE $table SET name=? WHERE id=?")->execute([$name,$id]);else db()->prepare("INSERT INTO $table(name) VALUES(?)")->execute([$name]);flash('success',$label.' saved.');}else flash('danger','Enter a name.');}if($act==='toggle')db()->prepare("UPDATE $table SET active=1-active WHERE id=?")->execute([(int)$_POST['id']]);go('catalog.php?type='.$type);}$term=trim($_GET['q']??'');$q=db()->prepare("SELECT * FROM $table WHERE name LIKE ? ORDER BY name");$q->execute(["%$term%"]);page_start($label.' management',true); ?><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><form class="d-flex gap-2 mb-3"><input type="hidden" name="type" value="<?= e($type) ?>"><input class="form-control" name="q" value="<?= e($term) ?>" placeholder="Search <?= e(strtolower($label)) ?>"><button class="btn btn-primary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($q as $x): ?><tr><td><?= e($x['name']) ?></td><td><?= $x['active']?'Active':'Inactive' ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="toggle"><input type="hidden" name="id" value="<?= $x['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Toggle</button></form></td></tr><?php endforeach ?></tbody></table></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Add <?= e(strtolower($label)) ?></h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="save"><input class="form-control mb-3" name="name" maxlength="100" required><button class="btn btn-primary">Add</button></form></div></div></div></div><?php page_end(); ?>
